class Solution:
    def shipWithinDays(self, weights: List[int], days: int) -> int:
        def feasible(cap: int) -> bool:
            used, load = 1, 0
            for w in weights:                 # one pass: greedily fill each day
                if load + w > cap:
                    used += 1
                    load = 0
                load += w
            return used <= days

        lo, hi = max(weights), sum(weights)   # smallest possible / one-day capacity
        while lo < hi:                        # binary search on the capacity
            mid = (lo + hi) // 2
            if feasible(mid):
                hi = mid
            else:
                lo = mid + 1
        return lo
